/**
 * Header parsing, checked against real files generated by macOS `sips` and
 * `afconvert` rather than hand-written bytes. Skips where those tools are missing.
 */
import { describe, expect, test } from "bun:test";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { bandFor, inspect, specsFor, type AudioFacts, type ImageFacts } from "./media";

const SRC = "/System/Library/CoreServices/DefaultDesktop.heic";
const SND = "/System/Library/Sounds/Glass.aiff";
const canImage = existsSync(SRC) && existsSync("/usr/bin/sips");
const canAudio = existsSync(SND) && existsSync("/usr/bin/afconvert");
const dir = mkdtempSync(join(tmpdir(), "media-"));

const image = (fmt: string, w: number, h: number, name: string) => {
  execFileSync("/usr/bin/sips", ["-s", "format", fmt, "--resampleHeightWidth", String(h), String(w), SRC, "--out", join(dir, name)], { stdio: "ignore" });
  return readFileSync(join(dir, name));
};
const audio = (spec: string, name: string) => {
  execFileSync("/usr/bin/afconvert", ["-f", "WAVE", "-d", spec, "-c", "2", SND, join(dir, name)], { stdio: "ignore" });
  return readFileSync(join(dir, name));
};

describe.if(canImage)("images", () => {
  test("PNG dimensions", () => {
    const f = inspect(image("png", 1200, 1200, "a.png")) as ImageFacts;
    expect(f).toMatchObject({ kind: "image", format: "png", width: 1200, height: 1200, square: true });
  });

  test("JPEG dimensions come from the SOF marker, wherever it is", () => {
    const f = inspect(image("jpeg", 3000, 3000, "b.jpg")) as ImageFacts;
    expect(f).toMatchObject({ kind: "image", format: "jpg", width: 3000, height: 3000 });
  });

  test("a non-square cover is caught — every store wants 1:1", () => {
    const f = inspect(image("jpeg", 1000, 800, "c.jpg")) as ImageFacts;
    expect(f.square).toBe(false);
  });

  test("TIFF SHORT tags are not read as LONG", () => {
    // A SHORT tag read as a LONG reports 800px as 52,428,800px.
    const f = inspect(image("tiff", 1000, 800, "d.tiff")) as ImageFacts;
    expect(f.width).toBe(1000);
    expect(f.height).toBe(800);
  });

  test("the format comes from the bytes, not the name", () => {
    // The store reads bytes, not the extension.
    expect((inspect(image("png", 640, 640, "lies.jpg")) as ImageFacts).format).toBe("png");
  });
});

describe.if(canAudio)("audio", () => {
  test("WAV 16-bit/44.1k", () => {
    expect(inspect(audio("LEI16@44100", "cd.wav"))).toMatchObject({ kind: "audio", format: "wav", bitDepth: 16, sampleRate: 44100, channels: 2 });
  });

  test("WAV 24-bit/44.1k, walking past a non-fmt chunk", () => {
    expect(inspect(audio("LEI24@44100", "m.wav"))).toMatchObject({ format: "wav", bitDepth: 24, sampleRate: 44100 });
  });

  test("AIFF's 80-bit extended sample rate is decoded", () => {
    const f = inspect(readFileSync(SND)) as AudioFacts;
    expect(f.kind).toBe("audio");
    expect(f.format).toBe("aiff");
    expect(f.sampleRate).toBeGreaterThan(8000);
  });
});

describe("what it refuses to guess", () => {
  test("an unrecognised file is unknown, never a guess", () => {
    const f = inspect(new TextEncoder().encode("this is a text file, not a master"));
    expect(f.kind).toBe("unknown");
  });

  test("an empty buffer does not throw", () => {
    expect(inspect(new Uint8Array(0)).kind).toBe("unknown");
  });
});

describe("bands, as the checklist speaks", () => {
  test("the boundaries are the real market thresholds", () => {
    expect(bandFor(999)).toBe("under 1000");
    expect(bandFor(1000)).toBe("1000 to 1599");
    expect(bandFor(1400)).toBe("1000 to 1599"); // CD Baby's floor sits inside this band
    expect(bandFor(1600)).toBe("1600 to 2999");
    expect(bandFor(3000)).toBe("3000 or more");
  });

  test("a rate nobody bands returns null rather than the nearest", () => {
    expect(specsFor({ kind: "audio", format: "wav", bitDepth: 8, sampleRate: 22050, channels: 1 })).toBeNull();
  });
});
